from pathlib import Path
import json,html,shutil,os,re,hashlib
import benchmark_pages
import model_pages
ROOT=Path(__file__).parent;D=ROOT/'docs';D.mkdir(exist_ok=True)
# These folders contain only generated pages and exported evidence.
for generated in ('models','evaluations','data/evidence','assets/model-icons'):
 path=D/generated
 if path.exists():shutil.rmtree(path)
GH='https://github.com/MotionChallenge-Project'
BASE=os.environ.get('SITE_BASE_PATH','/motion-challenge-project').rstrip('/')
SITE_URL='https://motionchallenge-project.github.io'+BASE
WEBSITE_SOURCE=GH+'/motion-challenge-project/tree/website'
NAMES={'grit':'GRIT','heft':'HEFT','sonic':'SONIC','mimic-lite':'MimicLite','scalebfm':'ScaleBFM','holomotion':'HoloMotion','humanoid-gpt':'Humanoid-GPT','protomotions':'ProtoMotions','bfm-zero':'BFM-Zero','twist2':'TWIST2'}
CONTENT=ROOT/'content'
MODELS=json.loads((CONTENT/'models.json').read_text())
NAMES={k:m['display_name'] for k,m in MODELS.items()}
CANDIDATES=[c for c in json.loads((CONTENT/'candidates.json').read_text()) if c.get('repository_available')]
TRACKS=json.loads((CONTENT/'tracks.json').read_text())
BENCHMARKS=benchmark_pages.load_catalog(CONTENT,TRACKS)
TRACK_BY_ID={t['id']:t for t in TRACKS}
RESULTS=json.loads((CONTENT/'results.json').read_text())
RESULTS_REVISION=hashlib.sha256((CONTENT/'results.json').read_bytes()+(CONTENT/'models.json').read_bytes()).hexdigest()[:12]
ASSET_REVISION=hashlib.sha256((ROOT/'style.css').read_bytes()+(ROOT/'app.js').read_bytes()).hexdigest()[:12]
rows=RESULTS['rows']
for row in rows:
 for field in ('adapter_code_url', 'core_code_url'):
  row[field]=model_pages.repository_location(row[field])
POLICY=json.loads((CONTENT/'publication_policy.json').read_text())
EXCLUDED=POLICY.get('excluded_models', {})
assert not any(k in EXCLUDED and not EXCLUDED[k].get('publish_results',True) for k in MODELS), 'Excluded models must stay out of the public catalog'
assert not any(r['model'] in EXCLUDED and not EXCLUDED[r['model']].get('publish_results',True) for r in rows), 'Withdrawn results cannot be republished'
assert all(r['mujoco_version']=='3.17.0' and r.get('adapter_code_url') and r.get('core_code_url') for r in rows), 'Only batch 3.17 results with pinned code may be published'
EVALUATED=len(set(r['model'] for r in rows))
for r in rows:
 r['icon']=MODELS[r['model']]['icon'];r['icon_label']=MODELS[r['model']]['icon_label'];r['icon_source']=MODELS[r['model']]['icon_source'];r['controller_type']=MODELS[r['model']]['controller_type'];r['label']=NAMES[r['model']];r['version']=MODELS[r['model']]['version'];r.setdefault('checkpoint_sha256',MODELS[r['model']]['runtime']['weights_sha256']);r['organization']=MODELS[r['model']]['organization'];r['organization_source']=MODELS[r['model']]['organization_source'];r['submitter']='Motion Challenge';r['status']='Trace verified';r['date']='2026-10-23';r['rank']=None;track=TRACK_BY_ID[r['track_id']];r['benchmark_id']=track['benchmark_id'];r['robot_id']=track['robot_id']
(D/'data').mkdir(exist_ok=True)
(D/'data/development-summary.json').write_text(json.dumps({'benchmarks':BENCHMARKS,'tracks':TRACKS,'rows':rows},indent=2))
nav=[('Leaderboard','/'),('Benchmarks','/benchmarks/'),('Models','/models/'),('Protocol','/protocol/'),('Submit','/submit/'),('Overview','/overview/')]
def page(path,title,body,active,canonical_path=None):
 body=model_pages.repository_location(body)
 folder=D/path.strip('/');folder.mkdir(exist_ok=True,parents=True)
 links=''.join(f'<a href="{url}" '+('aria-current="page"' if label==active else '')+f'>{label}</a>' for label,url in nav)
 (folder/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Motion Challenge</title><meta name="site-base-path" content="{BASE}"><meta name="results-revision" content="{RESULTS_REVISION}"><link rel="canonical" href="{SITE_URL}{canonical_path or path}"><meta name="description" content="Open, reproducible humanoid motion tracking evaluation. Shared protocols, independent model adapters, public review. LAFAN40 is our first dataset."><link rel="stylesheet" href="/style.css?v={ASSET_REVISION}"><script src="/app.js?v={ASSET_REVISION}" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/"><span class="mark">m<span>c</span></span><span>Motion Challenge</span></a><nav aria-label="Main navigation">{links}</nav><a class="github" href="{GH}">GitHub ↗</a></header><main id="main">{body}</main><footer><div><a class="brand" href="/">Motion Challenge</a><p>Open evaluation. Reproducible evidence.</p></div><div><a href="{GH}/MotionChallenge-Core">Core repository ↗</a><a href="/submit/">Contribute a controller</a><a href="/about/">About &amp; acknowledgments</a><a href="{WEBSITE_SOURCE}">Website source ↗</a></div><small>Open protocols · Public evidence<br>Updated 24 October 2026</small></footer></body></html>''')
def intro(kicker,title,text):return f'<section class="pagehead"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{text}</p></section>'
# Purpose-built schematic, not a robot rendering or reported motion trajectory.
figure='''<div class="hero-figure" aria-label="Schematic of reference and controller trajectories"><div class="figure-caption"><span class="dot"></span> ONE REFERENCE. MANY CONTROLLERS.</div><svg viewBox="0 0 650 500" role="img" aria-label="Two schematic robot poses with reference trajectories"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M 40 0 L 0 0 0 40" fill="none" stroke="#d5e2de" stroke-width=".7"/></pattern></defs><rect width="650" height="500" fill="url(#grid)"/><g fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M48 388 Q160 405 240 353 T440 320 T618 271" stroke="#8caf9f" stroke-width="2" stroke-dasharray="5 7"/><path d="M48 414 Q145 427 246 377 T442 347 T618 302" stroke="#125b50" stroke-width="3"/><g transform="translate(90 30)" stroke="#a9bdb5" stroke-width="8"><circle cx="190" cy="74" r="23"/><path d="M183 105 L159 184 L204 232 M179 116 L118 139 L101 190 M176 116 L223 154 L263 134 M159 184 L116 240 L84 318 M159 184 L197 248 L257 276"/><path d="M78 319 L103 321 M251 277 L274 277" stroke-width="12"/></g><g transform="translate(240 50)" stroke="#145b51" stroke-width="9"><circle cx="190" cy="74" r="23" fill="#f8faf7"/><path d="M184 105 L164 185 L205 222 M181 117 L130 153 L112 198 M181 117 L220 148 L265 131 M164 185 L131 247 L95 316 M164 185 L201 244 L255 277"/><path d="M90 316 L115 319 M250 277 L277 279" stroke-width="13"/></g></g><g fill="#e8f1ec" stroke="#145b51" stroke-width="2"><circle cx="404" cy="235" r="7"/><circle cx="441" cy="294" r="7"/><circle cx="371" cy="297" r="7"/><circle cx="421" cy="167" r="7"/></g><g font-family="monospace" font-size="12" fill="#667a73"><text x="36" y="465">REFERENCE → OBSERVATION → ACTION → EVIDENCE</text><text x="36" y="38">G1 / 29 DOF</text></g></svg><div class="figure-foot"><span><i class="line ref"></i>Reference</span><span><i class="line"></i>Controller</span><span>Schematic illustration</span></div></div>'''
page('/overview/','Open humanoid evaluation',f'''<section class="hero"><div><p class="eyebrow">OPEN HUMANOID EVALUATION</p><h1>Measure motion.<br><em>Make it reproducible.</em></h1><p class="lede">A unified evaluation core with public code and configurations for fair, reproducible comparisons of motion controllers.</p><div class="actions"><a class="button" href="/">Explore the leaderboard <span>↗</span></a><a class="text-link" href="{GH}/MotionChallenge-Core">Get the evaluator ↗</a></div><p class="small">First dataset: <a href="/benchmarks/lafan40/">LAFAN40</a> · Unitree G1 · 29 DoF</p></div>{figure}</section><section class="stats"><div><strong>40</strong><span>complete motion clips</span></div><div><strong>{EVALUATED}</strong><span>models evaluated</span></div><div><strong>6</strong><span>tracking-error views</span></div><div><strong>1</strong><span>shared evaluation core</span></div></section><section class="section"><div class="section-title"><p class="eyebrow">THE BENCHMARK COLLECTION</p><h2>Start with motion.<br>Build a common standard.</h2></div><a class="dataset-feature" href="/benchmarks/lafan40/"><div><span class="tag">DATASET 01</span><h3>LAFAN40</h3><p>Forty retargeted motion sequences. Every clip starts at its first frame and runs until completion or a declared failure.</p><span class="text-link">Explore dataset and protocol ↗</span></div><div class="dataset-number">40<small>motions · one checkpoint</small></div></a></section><section class="section tint"><p class="eyebrow">A SHARED EVALUATION CORE</p><h2>Fair, reproducible evaluation.</h2><div class="three"><article><span class="step">01</span><h3>One kernel</h3><p>Data, clocks, physics, termination and metrics are owned by a versioned core. Models bring their inference.</p></article><article><span class="step">02</span><h3>Faithful inference</h3><p>Each model uses its documented inference settings within the same evaluation core. Public code and configurations support fair, reproducible comparisons.</p></article><article><span class="step">03</span><h3>Inspectable results</h3><p>Bind checkpoints and source versions to a run. Recompute scores from pose traces, and make the reproduction record accessible.</p></article></div></section><section class="section split"><div><p class="eyebrow">PROJECT UPDATE · 23 OCT 2026</p><h2>The first LAFAN40 comparison.</h2></div><div><p>{EVALUATED} public models have completed MuJoCo 3.17 batch evaluation on all 40 motions. Explore success, completion and tracking errors, with checkpoint provenance on every model page.</p><a class="text-link" href="/">Explore the results ↗</a></div></section>''','Overview')
page('/benchmarks/','Benchmarks',benchmark_pages.directory(BENCHMARKS,TRACKS,intro),'Benchmarks')
for benchmark in BENCHMARKS:
 title,body=benchmark_pages.detail(CONTENT,benchmark,TRACKS)
 page('/benchmarks/'+benchmark['id']+'/',title,body,'Benchmarks')

leaderboard_body=intro('BENCHMARK RESULTS','Motion Challenge Leaderboard','Full-motion success first. Tracking accuracy with coverage. Compare organizations, checkpoints and tracking performance under one shared protocol.')+'''<section class="board-section"><div class="track-selectors"><label>Benchmark<select id="benchmark-select" aria-label="Benchmark"></select></label><label>Robot<select id="robot-select" aria-label="Robot"></select></label><label>Protocol<select id="protocol-select" aria-label="Protocol"></select></label><a id="track-details" href="/benchmarks/lafan40/">Dataset &amp; failure conditions ↗</a></div><div class="toolbar"><div><p id="track-caption" class="small">Loading benchmark…</p><p id="sort-caption" class="sort-caption" aria-live="polite"></p></div><label class="search">Find a model <input id="model-search" type="search" placeholder="Model, type or organization…"></label></div><div class="pagination pagination-top" aria-label="Table pagination"><label>Show <select id="page-size" aria-label="Models shown"><option value="5">Top 5</option><option value="10">Top 10</option><option value="15">Top 15</option><option value="25">Top 25</option><option value="all" selected>Top All</option></select></label><div><span data-page-range aria-live="polite"></span><button data-page="previous" aria-label="Previous page">← Previous</button><button data-page="next" aria-label="Next page">Next →</button></div></div><div class="table-scroll"><table id="leaderboard"><colgroup><col class="col-rank"><col class="col-model"><col class="col-type"><col class="col-org"><col class="col-success"><col class="col-completion"><col span="6" class="col-metric"></colgroup><thead><tr><th rowspan="3" scope="col">Rank</th><th rowspan="3" scope="col">Model</th><th rowspan="3" scope="col"><abbr title="Control policy family used by the evaluated checkpoint">Type</abbr></th><th rowspan="3" scope="col">Organization</th><th rowspan="3" scope="col"><button data-sort="passed">Success ↑</button></th><th rowspan="3" scope="col"><button data-sort="completion_pct">Completion ↑</button></th><th colspan="6" scope="colgroup" class="metric-title">Mean per-body position error · MPBPE <span>mm ↓</span><small>14 key bodies · lower is better</small></th></tr><tr><th colspan="3" scope="colgroup" class="metric-group">Early termination<small>Until first failure, including the failure frame</small></th><th colspan="3" scope="colgroup" class="metric-group full-motion">No termination<small>Entire motion, including post-failure states</small></th></tr><tr><th scope="col"><button data-sort="mpjpe_xy_yaw_aligned_m">XY + yaw ↓</button></th><th scope="col"><button data-sort="mpjpe_xy_aligned_m">XY only ↓</button></th><th scope="col"><button data-sort="mpjpe_world_m">No alignment ↓</button></th><th scope="col"><button data-sort="full_mpjpe_xy_yaw_aligned_m">XY + yaw ↓</button></th><th scope="col"><button data-sort="full_mpjpe_xy_aligned_m">XY only ↓</button></th><th scope="col"><button data-sort="full_mpjpe_world_m">No alignment ↓</button></th></tr></thead><tbody></tbody></table><p id="empty" hidden>No models match your search.</p></div><div class="pagination pagination-bottom" aria-label="Table pagination"><div><span data-page-range aria-live="polite"></span><button data-page="previous" aria-label="Previous page">← Previous</button><button data-page="next" aria-label="Next page">Next →</button></div></div><p class="table-note"><strong>Type:</strong> Dense = continuous dense policies (MLP, convolutional, graph or Transformer); FSQ = finite scalar quantization; MoE = mixture of experts; FB = forward-backward latent policy. Labels describe the evaluated controller; open a label for its source.</p><p class="table-note">MuJoCo 3.17.0 batch evaluations are running. One evaluation reports success, completion and six tracking-error views. Only MuJoCo 3.17.0 batch results are published. <a href="https://github.com/MotionChallenge-Project/MotionChallenge-Core">Published evaluator ↗</a></p><p class="table-note"><strong>Shared rules. Public code. Reproducible runs.</strong> Within each benchmark, robot and protocol, the core fixes data, physics, failures and scoring. Each entry identifies its checkpoint and inference implementation.</p><p class="table-note">Rank follows the selected metric, always best first: higher success or completion, lower tracking error. The default is success, then completion. Medals mark the top three. MPBPE averages 14 body-origin distances over frames, then equally over 40 clips. Early-termination errors cover the observed prefix. No-termination errors cover the entire motion. A dash means that the full run has not yet been published.</p><a class="text-link" href="/data/development-summary.json" download>Download results (JSON) ↓</a></section><section class="section three"><article><h3>Success</h3><p>A clip passes only if it reaches the final reference frame without any declared failure. All 40 clips use the same checkpoint.</p></article><article><h3>Completion</h3><p>Mean fraction of motion completed before failure. Reported alongside tracking error to describe how much of each motion was completed.</p></article><article><h3>Six tracking-error views</h3><p>Each rollout protocol reports XY + yaw, XY only and no alignment. These remove horizontal translation and heading, translation only, or neither. Height is retained in all six views.</p><a href="/protocol/#alignment">Metric definitions →</a></article></section>'''
leaderboard_body=leaderboard_body.replace('class="pagehead"','class="pagehead leaderboard-head"',1)
page('/','Leaderboard',leaderboard_body,'Leaderboard')
page('/leaderboard/','Leaderboard',leaderboard_body,'Leaderboard',canonical_path='/')
model_pages.render(MODELS, rows, TRACKS, CONTENT, GH, page, intro)
page('/protocol/','Evaluation protocol',intro('EVALUATION PROTOCOL','Evaluation protocol','A versioned protocol separates model inference from the conditions under which it is measured.')+f'''<div class="docs-layout"><aside><a href="#contract">Evaluation contract</a><a href="#alignment">Alignment metrics</a><a href="#inference">Author inference</a><a href="#evidence">Evidence & limits</a></aside><article class="docs"><section id="contract"><h2>01 · A fixed evaluation contract</h2><p>The shared core uses official <code>mujoco.batch</code> with MuJoCo 3.17.0. Every model keeps its native policy clock and independent history; PD is recomputed every physics step. Download and evaluation progress is emitted every five seconds. Only MuJoCo 3.17.0 batch is supported by the public evaluation entrypoint.</p><p>The core controls source data, interpolation, robot asset, physics, reset state, clocks, termination and scoring. The adapter controls observations, native history/recurrent state, network inference and action processing.</p><p>LAFAN40 starts from the first reference pose and velocity. Every clip runs to its exact last timestamp, including after the first tracking failure, without resetting. Reference queries outside the clip are clamped without shortening the episode. No evaluation noise or randomization; friction is 1.</p><h3>Failure conditions</h3><ul><li>Absolute torso height error exceeds 0.25 m.</li><li>Reference-versus-actual projected-gravity Z difference exceeds 0.8.</li><li>Maximum wrist or ankle world-height error exceeds 0.25 m.</li></ul><p>See <a href="/benchmarks/lafan40/#failure-conditions">LAFAN40 failure conditions</a> for formulas, exact bodies and endpoint behavior. No additional XY or tracking-precision threshold is introduced. The complete suite and one checkpoint are required. A smoke truncation or infrastructure failure cannot be counted as a passed motion.</p></section><section id="alignment"><h2>02 · Three views of tracking error</h2><div class="metric-box"><h3>XY + yaw alignment</h3><p>Remove per-frame horizontal root translation and relative world-Z heading before measuring 14 keybody positions. Retain height and tilt. This describes local body tracking with horizontal trajectory and heading factored out.</p></div><div class="metric-box"><h3>XY alignment</h3><p>Remove only per-frame root XY translation. Retain heading, height and tilt, so a heading mismatch remains visible.</p></div><div class="metric-box"><h3>No alignment</h3><p>Compare world-frame body positions directly. Global translation and heading drift remain in the result.</p></div><p>MPBPE means mean per-body position error: Euclidean distances across 14 named body origins, reported in millimetres. The legacy JSON keys are named mpjpe_*_m; these measure body positions, not joint angles. Joint MAE is separately measured in radians.</p><p>The XY + yaw transform uses the closest relative world-Z rotation derived from both pelvis orientations. Samples with ambiguous heading are retained and reported. See the implementation for the exact formula.</p><h3>Coverage is part of the interpretation</h3><p>One complete rollout produces six metric views: three alignment methods over the prefix through the first failure, and the same three over the entire motion. For each view, first average frames within a motion, then equally across motions. Success and completion retain the same first-failure definition. Both time ranges are computed from the same complete trajectory, without resetting after failure.</p></section><section id="inference"><h2>03 · Follow the author's inference</h2><p>Pin the source and checkpoint. Check observations, joint order, coordinate frames, control frequency, reference lookahead, normalization, history initialization, recurrent memory, action scales, clipping, gains and filters. Compare input tensors, raw network outputs and final motor targets on identical sequences, including reset and endpoint cases.</p><p>Document benchmark-specific differences. A shared robot and physics protocol can differ from an author's training environment; matching inference does not reproduce their paper scores. Checkpoint conversion requires a numerical equivalence test.</p></section><section id="evidence"><h2>04 · Reproducible results</h2><ol><li><strong>Artifact provenance:</strong> fixed checkpoint, source revision and dependency lock.</li><li><strong>Inference parity:</strong> tested against author-maintained inference.</li><li><strong>Complete evaluation:</strong> every clip under one protocol and checkpoint.</li><li><strong>Trace verification:</strong> independently recompute failures and metrics.</li></ol><p>Each result links its evaluation code, checkpoint, configuration and independently recomputed trajectory metrics. The shared core applies the same benchmark conditions to every model.</p><a class="text-link" href="{GH}/MotionChallenge-Core/blob/main/docs/PROTOCOL.md">Read the implementation-level protocol ↗</a></section></article></div>''','Protocol')
page('/submit/','Submit a controller',intro('CONTRIBUTE TO THE BENCHMARK','Make your result reproducible.','A model repository, a pinned checkpoint, and a verifiable run. LAFAN40 is the first suite; the integration contract is shared.')+f'''<section class="section three steps"><article><span class="step">01</span><h3>Adapt inference</h3><p>Create your own repository with the core as a root-level submodule. Implement reset, act and close. Preserve the author's deployment behavior.</p><a href="{GH}/MotionChallenge-Core/blob/main/docs/ADAPTERS.md">SDK and adapter guide ↗</a></article><article><span class="step">02</span><h3>Run the whole suite</h3><p>Use one checkpoint and the fixed protocol. Keep outputs outside Git. Submit full pose traces, hashes, receipts and inference-parity evidence.</p><a href="/protocol/">Read the evaluation protocol →</a></article><article><span class="step">03</span><h3>Request review</h3><p>Open an issue linking your adapter and external result artifacts. Include the actual submitter, source/checkpoint versions, training-data overlap and any adaptations.</p><a href="{GH}/MotionChallenge-Core/issues/new">Open a submission issue ↗</a></article></section><section class="section tint"><h2>A small adapter. A shared kernel.</h2><pre><code>motion-challenge-your-model/
├── motion-challenge/  # pinned core submodule
├── adapter.py         # inference only
├── runtime.json       # clocks, artifacts, input contract
├── provenance.json    # source and review evidence
├── evaluate.py        # shared core entrypoint
├── pyproject.toml
└── uv.lock</code></pre><p>The core owns datasets, physics, metrics and verification. Model repositories do not copy or override evaluation logic. Checkpoints, data and results live in local caches or external artifact storage.</p></section><section class="section" id="datasets"><h2>Propose another dataset</h2><p>Publish a manifest with immutable source revisions, file hashes, frame rate, joint order and the complete motion set. Define a distinct protocol version and benchmark identity. Preserve difficult clips, document licensing and overlap, and keep scores in their own track.</p><a class="text-link" href="{GH}/MotionChallenge-Core/blob/main/docs/BENCHMARKS.md">Dataset integration contract ↗</a></section>''','Submit')
page('/about/','About the project',intro('ABOUT MOTION CHALLENGE','Fair, reproducible motion evaluation.','An open-source benchmark that uses a unified evaluation core, public code and configurations for fair, reproducible model comparisons.')+f'''<section class="section docs"><h2>What we are building</h2><p>A collection of benchmarks with one reusable core and independent model adapters. LAFAN40 on G1 29DoF is the first dataset. We publish the evaluation code and distinguish maintainer reproductions from author submissions.</p><p>Every metric follows the same rules within its benchmark, robot and protocol. The evaluation code is public, checkpoint and source revisions are pinned, and results have reproduction commands and per-motion evidence. Author-specific observations, control frequency and action processing are documented separately. Results are tied to checkpoint and protocol versions. Corrections should remain visible, with previous versions retained. Questions about an adaptation or score belong in the public issue tracker.</p><a class="button" href="{GH}/MotionChallenge-Core/issues">Discuss a result ↗</a><h2>Acknowledgments</h2><p>We thank the authors of the released controllers, LAFAN1 and the LAFAN1 retargeting dataset, MuJoCo and mjlab. Model names identify upstream work, not endorsement of this benchmark.</p><p>The site's organization was informed by the separation of protocol, aggregate results and task detail in <a href="https://robotwin-platform.github.io/leaderboard">RoboTwin</a>, the benchmark and documentation structure of <a href="https://robocasa.ai/">RoboCasa</a>, the public evaluation presentation of <a href="https://robochallenge.ai/home">RoboChallenge</a>, and <a href="https://github.com/Roboparty/MimicLite">MimicLite's project documentation</a>. This project is independent of those teams.</p><h2>Current limitations</h2><p>The current track uses privileged simulator state and nominal canonical physics. Inference reviews and independent adapter reruns are in progress. Benchmark scores do not establish real-world performance or generalization beyond this dataset.</p></section>''','Overview')
shutil.copytree(CONTENT/'evidence',D/'data/evidence',dirs_exist_ok=True)
shutil.copytree(ROOT/'assets/model-icons',D/'assets/model-icons',dirs_exist_ok=True,ignore=shutil.ignore_patterns('README.md'))
shutil.copy2(ROOT/'app.js',D/'app.js')
shutil.copy2(ROOT/'style.css',D/'style.css')
(D/'.nojekyll').write_text('')
for document in D.rglob('*.html'):
 text=document.read_text()
 text=re.sub(r'(href|src)="/(?!/)',lambda m:m.group(1)+'="'+BASE+'/',text)
 document.write_text(text)
print('Built',len(list(D.rglob('index.html'))),'pages')
